<script lang="ts">
  import { onMount } from 'svelte';
  import { CalendarDays, ArrowLeft, Users } from '@lucide/svelte';
  import Dropdown, { type DropdownOption } from '$lib/components/ui/Dropdown.svelte';
  import { featureApiJson } from '$lib/client/feature-api.js';
  import { notify } from '$lib/client/notifications.js';
  const { data } = $props() as { data: { slug: string } };
  type EventRow = { id:string; title:string; description:string|null; eventType:string; locationText:string|null; onlineUrl:string|null; startsAt:string; endsAt:string|null; timezone:string; capacity:number|null; goingCount:number; interestedCount:number; myRsvp:string|null; status:string };
  let events = $state<EventRow[]>([]); let loading = $state(true); let error = $state(''); let creating = $state(false); let busy = $state(false);
  let title = $state(''); let description = $state(''); let eventType = $state('online'); let startsAt = $state(''); let endsAt = $state(''); let locationText = $state(''); let onlineUrl = $state(''); let timezone = $state(Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC'); let capacity = $state(''); let visibility = $state('community');
  const typeOptions: DropdownOption[] = [{value:'online',label:'Online'},{value:'in_person',label:'In person'},{value:'hybrid',label:'Hybrid'}];
  const visibilityOptions: DropdownOption[] = [{value:'community',label:'Community members'},{value:'public',label:'Public event'}];
  async function loadEvents() { loading = true; error=''; try { const result = await featureApiJson<{events:EventRow[]}>(`/events?community=${encodeURIComponent(data.slug)}&limit=80`); events=result.events; } catch(e) { error=e instanceof Error?e.message:'Could not load events.'; } finally { loading=false; } }
  async function createEvent() {
    if (!title.trim() || !startsAt) { error='Add an event title and start time.'; return; }
    busy=true; error='';
    try { const payload = { title, description, eventType, locationText, onlineUrl, startsAt: new Date(startsAt).toISOString(), endsAt: endsAt ? new Date(endsAt).toISOString() : '', timezone, capacity: capacity ? Number(capacity) : null, visibility };
      await featureApiJson(`/communities/${encodeURIComponent(data.slug)}/events`, { method:'POST', body:JSON.stringify(payload) });
      title=''; description=''; onlineUrl=''; locationText=''; startsAt=''; endsAt=''; capacity=''; creating=false; notify('Event created.','success'); await loadEvents();
    } catch(e) { error=e instanceof Error?e.message:'Could not create event.'; notify(error,'error'); } finally { busy=false; }
  }
  async function rsvp(event:EventRow) { try { await featureApiJson(`/events/${encodeURIComponent(event.id)}/rsvp`, { method:event.myRsvp?'DELETE':'PUT', ...(event.myRsvp?{}:{body:JSON.stringify({status:'going'})}) }); await loadEvents(); } catch(e) { notify(e instanceof Error?e.message:'Could not RSVP.','error'); } }
  onMount(() => { void loadEvents(); });
</script>
<svelte:head><title>Events in c/{data.slug} · Nexus</title></svelte:head>
<div class="mx-auto w-full max-w-[1500px] px-3 pb-20 sm:px-6">
  <a href={`/c/${encodeURIComponent(data.slug)}`} class="inline-flex items-center gap-2 text-xs font-bold text-slate-400 hover:text-white"><ArrowLeft size={15}/> c/{data.slug}</a>
  <header class="mt-4 flex flex-wrap items-end justify-between gap-4 border-b border-white/10 pb-5"><div><div class="flex items-center gap-2 text-xs font-bold uppercase tracking-widest text-orange-300"><CalendarDays size={16}/> Community calendar</div><h1 class="mt-2 text-3xl font-black text-white">Events in c/{data.slug}</h1><p class="mt-2 text-sm text-slate-400">Plan an AMA, study session, tournament, or community meetup.</p></div><button onclick={() => creating=!creating} class="rounded-full bg-orange-400 px-4 py-2.5 text-sm font-extrabold text-slate-950">{creating?'Cancel':'＋ Create event'}</button></header>
  {#if creating}<section class="mt-4 rounded-xl border border-white/10 bg-[#101719] p-4 sm:p-5"><h2 class="text-lg font-extrabold text-white">New community event</h2><div class="mt-4 grid gap-3 sm:grid-cols-2"><label class="grid gap-1.5 text-xs font-bold text-slate-300 sm:col-span-2">Event title<input bind:value={title} maxlength="140" class="rounded-lg border border-white/10 bg-black/20 p-3 text-sm text-white" placeholder="Community game night" /></label><label class="grid gap-1.5 text-xs font-bold text-slate-300">Format<Dropdown label="Event format" options={typeOptions} value={eventType} onChange={v=>eventType=v} fullWidth/></label><label class="grid gap-1.5 text-xs font-bold text-slate-300">Visibility<Dropdown label="Event visibility" options={visibilityOptions} value={visibility} onChange={v=>visibility=v} fullWidth/></label><label class="grid gap-1.5 text-xs font-bold text-slate-300">Starts at<input bind:value={startsAt} type="datetime-local" class="rounded-lg border border-white/10 bg-black/20 p-3 text-sm text-white" /></label><label class="grid gap-1.5 text-xs font-bold text-slate-300">Ends at (optional)<input bind:value={endsAt} type="datetime-local" class="rounded-lg border border-white/10 bg-black/20 p-3 text-sm text-white" /></label>{#if eventType!=='in_person'}<label class="grid gap-1.5 text-xs font-bold text-slate-300 sm:col-span-2">Meeting URL<input bind:value={onlineUrl} type="url" placeholder="https://…" class="rounded-lg border border-white/10 bg-black/20 p-3 text-sm text-white" /></label>{/if}{#if eventType!=='online'}<label class="grid gap-1.5 text-xs font-bold text-slate-300 sm:col-span-2">Location<input bind:value={locationText} maxlength="180" class="rounded-lg border border-white/10 bg-black/20 p-3 text-sm text-white" /></label>{/if}<label class="grid gap-1.5 text-xs font-bold text-slate-300">Timezone<input bind:value={timezone} maxlength="80" class="rounded-lg border border-white/10 bg-black/20 p-3 text-sm text-white" /></label><label class="grid gap-1.5 text-xs font-bold text-slate-300">Capacity (optional)<input bind:value={capacity} type="number" min="1" max="100000" class="rounded-lg border border-white/10 bg-black/20 p-3 text-sm text-white" /></label><label class="grid gap-1.5 text-xs font-bold text-slate-300 sm:col-span-2">Description<textarea bind:value={description} rows="3" maxlength="5000" class="rounded-lg border border-white/10 bg-black/20 p-3 text-sm text-white" placeholder="What should attendees know?" /></label></div>{#if error}<p role="alert" class="mt-3 text-sm text-rose-200">{error}</p>{/if}<div class="mt-4 flex justify-end"><button onclick={createEvent} disabled={busy} class="rounded-full bg-orange-400 px-4 py-2.5 text-sm font-extrabold text-slate-950 disabled:opacity-50">{busy?'Publishing…':'Publish event'}</button></div></section>{/if}
  {#if error && !creating}<p class="mt-4 rounded-xl border border-rose-300/20 p-3 text-sm text-rose-200">{error}</p>{/if}
  {#if loading}<p class="mt-8 text-sm text-slate-400">Loading events…</p>{:else if !events.length}<div class="mt-5 rounded-xl border border-dashed border-white/15 p-10 text-center"><CalendarDays size={30} class="mx-auto text-slate-500"/><h2 class="mt-3 font-bold text-white">No upcoming events</h2><p class="mt-2 text-sm text-slate-400">Be the first to get the community together.</p></div>{:else}<div class="mt-5 grid gap-3 md:grid-cols-2 xl:grid-cols-3">{#each events as event (event.id)}<article class="rounded-xl border border-white/10 bg-[#101719] p-4"><span class="text-[10px] font-extrabold uppercase text-orange-300">{event.eventType.replace('_',' ')}</span><h2 class="mt-2 text-lg font-extrabold text-white">{event.title}</h2><p class="mt-2 text-sm leading-6 text-slate-400">{event.description||'Community gathering.'}</p><p class="mt-4 text-xs text-slate-300">{new Date(event.startsAt).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'})}</p><div class="mt-3 flex items-center justify-between border-t border-white/[.07] pt-3"><span class="flex items-center gap-1 text-xs text-slate-400"><Users size={14}/>{event.goingCount} going · {event.interestedCount} interested</span><button onclick={()=>void rsvp(event)} class="rounded-full border border-white/10 px-3 py-2 text-xs font-bold text-slate-200 hover:border-orange-300/40">{event.myRsvp?'Cancel RSVP':'I’m going'}</button></div></article>{/each}</div>{/if}
</div>
